from taf.cloud.ncir.ncirs.ncir_17a import Ncir17A
from taf.cloud.ncir.exception import NcirVersionNotSupported


class NcirVersions(object):
    ncir_17a = Ncir17A


class NcirClient(object):
    @classmethod
    def create_connection(cls, address, version, **version_parameters):
        version_type = getattr(NcirVersions, version, None)
        if version_type is None:
            raise NcirVersionNotSupported("{} NCIR version is not supported yet".format(
                version
            ))
        connection = version_type()
        connection.connect(address, **version_parameters)
        return connection
